import { useCallback, useEffect, useMemo, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { FetchDataOptions } from '@/types/table.types';
import { Interview } from '../../types/interview.types';
import UnderlineHeading from '@/components/heading/UnderlineHeading';
import { Input } from '@/components/ui/input';
import SearchIcon from '@/components/icons/Search';
import { STATIC_INTERVIEWS, USE_STATIC_DATA } from '../../data/configs.data';
import InterviewCard from './InterviewCard';

const InterviewsList = () => {
    const [data, setData] = useState<Interview[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const [pageIndex, setPageIndex] = useState(0);
    const [globalFilter, setGlobalFilter] = useState('');

    const fetchData = useCallback(async (options: FetchDataOptions) => {
        setIsLoading(true);

        try {
            const response = await apiGet({
                endpoint: endpoints.interview.list,
                queryParams: { page: options.pageIndex + 1, ...options.filters, search: options.globalFilter },
            });

            setData(response.data.data.data);
            setPageCount(Math.ceil(response.data.data.pagination.total / 10));
            setTotalCount(response.data.data.pagination.total);
        } catch (error) {
            console.error('Error fetching data:', error);
        } finally {
            setIsLoading(false);
        }
    }, []);

    useEffect(() => {
        if (USE_STATIC_DATA) {
            const normalizedSearch = globalFilter.trim().toLowerCase();
            const filteredData = STATIC_INTERVIEWS.filter((item) => {
                const candidateName = item.name?.toLowerCase() ?? '';
                const jobTitle = item.description?.toLowerCase() ?? '';
                return candidateName.includes(normalizedSearch) || jobTitle.includes(normalizedSearch);
            });

            const pageSize = 10;
            const start = pageIndex * pageSize;
            const end = start + pageSize;
            const paginatedData = filteredData.slice(start, end);

            setData(paginatedData);
            setTotalCount(filteredData.length);
            setPageCount(Math.max(Math.ceil(filteredData.length / pageSize), 1));
            return;
        }

        fetchData({ pageIndex, pageSize: 10, sorting: [], globalFilter, filters: {} });
    }, [fetchData, globalFilter, pageIndex]);

    const rowsRangeText = useMemo(() => {
        if (totalCount === 0) {
            return 'عرض 0 إلى 0 من 0';
        }

        const start = pageIndex * 10 + 1;
        const end = Math.min((pageIndex + 1) * 10, totalCount);
        return `عرض ${start} إلى ${end} من ${totalCount}`;
    }, [pageIndex, totalCount]);

    return (
        <div className="mb-10 mt-4 overflow-hidden rounded-lg border border-[#E8E7EA] shadow-[0px_4px_4px_-1px_#0C0C0D0D,0px_4px_4px_-1px_#0C0C0D1A]">
            <div className="flex flex-col gap-3 border-b border-[#E8E7EA] p-3 md:flex-row md:items-center md:justify-between md:gap-4 md:p-4">
                <UnderlineHeading text="قائمة المقابلات" />
                <div className="flex h-[38px] w-full max-w-full flex-row items-center rounded-[6px] border border-white-blue-300 bg-white-blue-50 p-2 md:w-[280px] md:max-w-[280px]">
                    <Input
                        placeholder="ابحث باسم المرشح"
                        value={globalFilter}
                        onChange={(event) => {
                            setPageIndex(0);
                            setGlobalFilter(event.target.value);
                        }}
                        className="text-white-blue-800 p-0 tracking-normal text-xs lg:text-sm lg:leading-[16.8px] border-none outline-none focus-visible:ring-0 placeholder:text-white-blue-800"
                    />
                    <button type="button" className="bg-transparent border-none">
                        <SearchIcon className="text-white-blue-800" />
                    </button>
                </div>
            </div>

            <div className="p-3 sm:p-4">
                {isLoading ? (
                    <div className="py-8 text-center text-sm text-white-blue-900">جاري التحميل...</div>
                ) : data.length === 0 ? (
                    <div className="py-8 text-center text-sm text-white-blue-900">لا توجد مقابلات متاحة</div>
                ) : (
                    <InterviewCard data={data} />
                )}
            </div>

            <div className="flex flex-col gap-3 px-3 pb-3 text-xs text-[#625E74] sm:px-4 sm:pb-4 md:flex-row md:items-center md:justify-between">
                <p className="text-center md:text-right">{rowsRangeText}</p>
                <div className="flex w-full items-center justify-center gap-2 md:w-auto md:justify-start">
                    <button
                        type="button"
                        className="rounded border px-3 py-1.5 disabled:opacity-50"
                        disabled={pageIndex === 0}
                        onClick={() => setPageIndex((prev) => Math.max(prev - 1, 0))}
                    >
                        السابق
                    </button>
                    <span>
                        {pageIndex + 1} / {Math.max(pageCount, 1)}
                    </span>
                    <button
                        type="button"
                        className="rounded border px-3 py-1.5 disabled:opacity-50"
                        disabled={pageIndex + 1 >= pageCount}
                        onClick={() => setPageIndex((prev) => prev + 1)}
                    >
                        التالي
                    </button>
                </div>
            </div>
        </div>
    );
};

export default InterviewsList;
